import{_ as o,o as n,c as s,a2 as i}from"./chunks/framework.KobcctIO.js";const g=JSON.parse('{"title":"Synchronisation Cloud Horizon (Guide Joueur)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/players/cloud-sync.md","filePath":"fr/guide/players/cloud-sync.md"}'),r={name:"fr/guide/players/cloud-sync.md"};function t(a,e,l,u,c,d){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="synchronisation-cloud-horizon-guide-joueur" tabindex="-1">Synchronisation Cloud Horizon (Guide Joueur) <a class="header-anchor" href="#synchronisation-cloud-horizon-guide-joueur" aria-label="Permalink to &quot;Synchronisation Cloud Horizon (Guide Joueur)&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Technologie-Delta%20Sync-blue.svg" alt="Delta Sync"><img src="https://img.shields.io/badge/Fournisseurs-Google%20Drive%20%7C%20Dropbox%20%7C%20OneDrive-green.svg" alt="Fournisseurs"><img src="https://img.shields.io/badge/Chiffrement-AES--256--GCM-red.svg" alt="Chiffrement"></div><p>La technologie <strong>Horizon Cloud Sync</strong> est l&#39;une des innovations majeures de Gens Launcher. Elle vous permet de synchroniser automatiquement vos instances Minecraft (mondes en solo, réglages de touches, inventaires, packs et mods) entre plusieurs ordinateurs en utilisant votre propre stockage cloud personnel.</p><hr><h2 id="comment-fonctionne-la-synchronisation-cloud" tabindex="-1">Comment fonctionne la Synchronisation Cloud ? <a class="header-anchor" href="#comment-fonctionne-la-synchronisation-cloud" aria-label="Permalink to &quot;Comment fonctionne la Synchronisation Cloud ?&quot;">​</a></h2><p>Contrairement aux solutions classiques qui renvoient l&#39;intégralité d&#39;un dossier de 500 Mo à chaque partie, Gens-Horizon utilise la synchronisation différentielle (<strong>Delta Sync</strong>) :</p><ul><li>Seuls les fichiers modifiés depuis votre dernière session sont analysés.</li><li>Les données inchangées ne sont jamais retransférées.</li><li>Une session de jeu ne consomme que quelques mégaoctets de bande passante et prend quelques secondes à être synchronisée.</li></ul><hr><h2 id="connecter-un-fournisseur-cloud" tabindex="-1">Connecter un Fournisseur Cloud <a class="header-anchor" href="#connecter-un-fournisseur-cloud" aria-label="Permalink to &quot;Connecter un Fournisseur Cloud&quot;">​</a></h2><ol><li>Rendez-vous dans les <strong>Paramètres</strong> de Gens Launcher -&gt; onglet <strong>Horizon Cloud</strong>.</li><li>Choisissez votre fournisseur de stockage : <ul><li><strong>Google Drive</strong></li><li><strong>Dropbox</strong></li><li><strong>Microsoft OneDrive</strong></li></ul></li><li>Cliquez sur <strong>Se connecter</strong>. Une page d&#39;autorisation officielle sécurisée s&#39;ouvre dans votre navigateur web.</li><li>Accordez l&#39;accès à l&#39;application. Gens-Horizon chiffre les jetons d&#39;accès sur votre disque avec une clé unique liée au matériel de votre machine (<strong>PBKDF2</strong> 600 000 itérations + <strong>AES-256-GCM</strong>).</li><li>Une fois connecté, votre quota restant s&#39;affiche en temps réel dans l&#39;interface.</li></ol><hr><h2 id="activer-la-synchronisation-sur-une-instance" tabindex="-1">Activer la Synchronisation sur une Instance <a class="header-anchor" href="#activer-la-synchronisation-sur-une-instance" aria-label="Permalink to &quot;Activer la Synchronisation sur une Instance&quot;">​</a></h2><ol><li>Faites un clic droit sur l&#39;instance de votre choix -&gt; <strong>Paramètres</strong>.</li><li>Cochez l&#39;option <strong>Activer la Synchronisation Cloud Horizon</strong>.</li><li>Deux modes sont disponibles : <ul><li><strong>Mode Intelligent (Recommandé) :</strong> Gens Launcher vérifie la présence d&#39;une sauvegarde cloud plus récente avant de lancer le jeu, et envoie automatiquement vos modifications à la fermeture du jeu.</li><li><strong>Mode Manuel :</strong> Vous déclenchez l&#39;envoi ou la récupération quand vous le souhaitez à l&#39;aide des boutons <em>Envoyer au Cloud</em> et <em>Restaurer depuis le Cloud</em>.</li></ul></li></ol><hr><h2 id="historique-des-versions-et-restauration-rollback" tabindex="-1">Historique des Versions et Restauration (Rollback) <a class="header-anchor" href="#historique-des-versions-et-restauration-rollback" aria-label="Permalink to &quot;Historique des Versions et Restauration (Rollback)&quot;">​</a></h2><p>Si votre monde est corrompu ou si un mod endommage votre sauvegarde :</p><ol><li>Allez dans l&#39;onglet <strong>Cloud</strong> de l&#39;instance.</li><li>Consultez l&#39;historique chronologique de vos sessions de jeu.</li><li>Cliquez sur <strong>Restaurer à ce point</strong> pour rétablir exactement l&#39;état de vos fichiers à la date sélectionnée.</li></ol><hr><h2 id="securite-et-confidentialite-des-donnees" tabindex="-1">Sécurité et Confidentialité des Données <a class="header-anchor" href="#securite-et-confidentialite-des-donnees" aria-label="Permalink to &quot;Sécurité et Confidentialité des Données&quot;">​</a></h2><ul><li><strong>Votre stockage personnel :</strong> Vos sauvegardes sont stockées exclusivement sur votre propre compte cloud (Google, Dropbox, Microsoft). Aucun serveur tiers ne conserve vos fichiers.</li><li><strong>Protection par Verrouillage Atomique :</strong> Si vous laissez votre jeu allumé sur un premier PC, un fichier de verrouillage (<code>horizon.lock</code>) empêche tout conflit d&#39;écriture ou écrasement accidentel depuis un second ordinateur.</li></ul>',20)])])}const m=o(r,[["render",t]]);export{g as __pageData,m as default};
